
public class Quadrados {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		double n1, n2, n3, quad1, quad2, quad3,soma;
		n1=2;
		n2=3;
		n3=4;
		
		quad1 = n1*n1;
		quad2 = n2*n2;
		quad3 = n3*n3;
		
		soma = (quad1+quad2)+quad3;
		
		System.out.println("Soma dos quadrados é:" + soma);

	}

}
